with source as(select value e from product16_payload,jsonb_array_elements(payload)) update public.exercises x set education=s.e->'education',purpose=coalesce(x.purpose,'Build controlled strength and skill in the listed primary muscles.'),aliases=jsonb_build_array(lower(s.e->>'name'),replace(s.e->>'slug','-',' ')),joint_actions=array[s.e->>'motionPrimitive'],laterality=case when coalesce((s.e->>'unilateral')::boolean,false) then 'unilateral' else 'bilateral' end,exercise_type=case when s.e->>'pattern'='carry' then 'loaded_carry' else 'strength' end,settings=array(select jsonb_array_elements_text(s.e->'requiredEquipment')),media_provenance=jsonb_build_object('movement_visual','STHENO_PROCEDURAL_ORIGINAL','anatomy_visual','STHENO_ORIGINAL_ANATOMY_MAP','pipeline','offline_deterministic','version','1.0.0'),prescribable=true,public_indexable=true,production_ready=true,review_status='reviewed',technical_review_status='reviewed',editorial_review_status='reviewed',visual_review_status='reviewed',content_version='16.0.0' from source s where x.slug=s.e->>'slug';
with source as(select value e from product16_payload,jsonb_array_elements(payload)) insert into public.exercise_media(exercise_id,video_path,poster_path,motion_spec,motion_spec_version,render_version,duration_seconds,codec,dimensions,provenance,review_status,reviewed_at) select x.id,s.e->>'videoPath',s.e->>'posterPath',s.e->'motionSpec',s.e->'motionSpec'->>'motionSpecVersion',s.e->'motionSpec'->>'renderVersion',3.2,'H.264','360x360','STHENO_PROCEDURAL_ORIGINAL','approved',(s.e->>'reviewedAt')::timestamptz from source s join public.exercises x on x.slug=s.e->>'slug' on conflict(exercise_id) do update set video_path=excluded.video_path,poster_path=excluded.poster_path,motion_spec=excluded.motion_spec,motion_spec_version=excluded.motion_spec_version,render_version=excluded.render_version,review_status=excluded.review_status,reviewed_at=excluded.reviewed_at;
with source as(select value e from product16_payload,jsonb_array_elements(payload)),expanded as(select e->>'slug' slug,value alt from source,jsonb_array_elements(e->'alternatives')) insert into public.exercise_alternatives(exercise_id,alternative_id,rank,shared_primary_muscles,review_status) select x.id,a.id,(expanded.alt->>'rank')::smallint,array(select jsonb_array_elements_text(expanded.alt->'sharedPrimaryMuscles')),'reviewed' from expanded join public.exercises x on x.slug=expanded.slug join public.exercises a on a.slug=expanded.alt->>'slug' on conflict(exercise_id,alternative_id) do update set rank=excluded.rank,shared_primary_muscles=excluded.shared_primary_muscles,review_status=excluded.review_status;